-- Staging-only migration 214: supervised-learning review and undo hardening.
begin;
set local lock_timeout='10s';
set local statement_timeout='180s';
select pg_advisory_xact_lock(hashtextextended('pdc-staging-migration-214-supervised-learning-hardening',0));
select public.pdc_monitor_staging_guard();
do $guard$ begin
 if not public.pdc_monitor_staging_guard()
 or not exists(select 1 from public.pdc_staging_environment_sentinel where singleton and project_ref='cdsmnqxtyyoeoznmbidd')
 or to_regclass('public.pdc_production_environment_sentinel') is not null
 or not exists(select 1 from supabase_migrations.schema_migrations where version='213' and name='persistent_supervised_email_learning')
 or exists(select 1 from supabase_migrations.schema_migrations where version~'^[0-9]+$' and version::integer>213)
 or exists(select 1 from supabase_migrations.schema_migrations where version='214') then raise exception 'PDC_214_STAGING_OR_LEDGER_MISMATCH' using errcode='55000';end if;
end $guard$;

create table public.pdc_supervised_review_queue(
 review_id uuid primary key default gen_random_uuid(),operation_code text,source_description text not null,current_mapping text,
 reason text not null,scope jsonb not null,actor_id uuid not null references auth.users(id) on delete restrict,actor_email text not null,
 resolved_at timestamptz,resolution_rule_version_id uuid references public.pdc_supervised_rule_versions(version_id) on delete restrict,
 created_at timestamptz not null default clock_timestamp()
);
alter table public.pdc_supervised_review_queue enable row level security;
revoke all on table public.pdc_supervised_review_queue from public,anon,authenticated,service_role;
create trigger pdc_supervised_review_queue_immutable before update or delete on public.pdc_supervised_review_queue for each row execute function public.pdc_supervised_immutable_213();

create or replace function public.review_pdc_supervised_email_line_213(p_operation_line_id uuid,p_operation_code text,p_description text,p_existing_work_key text) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_admin_scope_213();r record;d text:=btrim(lower(regexp_replace(btrim(coalesce(p_description,'')),'[^a-zA-Z0-9]+',' ','g')));begin if not coalesce((s->>'ok')::boolean,false) then s:=public.pdc_supervised_monitor_scope_213();end if;if not coalesce((s->>'ok')::boolean,false) then return s;end if;select x.* into r from public.list_pdc_supervised_rules_213(false)x left join public.pdc_supervised_rule_aliases al on al.version_id=x.version_id where (x.match_kind='operation_code' and x.operation_code=upper(btrim(p_operation_code))) or (x.match_kind='exact_description' and x.normalized_description=d) or (x.match_kind='phrase' and (d like '%'||replace(x.phrase_category,'_',' ')||'%' or d like '%'||al.alias||'%')) order by case x.match_kind when 'operation_code' then 2 when 'exact_description' then 3 when 'phrase' then 4 else 9 end,x.priority desc,x.confidence desc,x.version_no desc limit 1;if found then return public.navision_backend_response(true,'deterministic_match',jsonb_build_object('operation_line_id',p_operation_line_id,'work_key',r.work_key,'version_id',r.version_id,'version_no',r.version_no,'precedence',r.match_kind));end if;if p_existing_work_key is not null then return public.navision_backend_response(true,'existing_mapping',jsonb_build_object('work_key',p_existing_work_key,'precedence','existing_mapping'));end if;return public.navision_backend_response(false,'inference_review_required');end$$;

create or replace function public.read_pdc_supervised_learning_rule(p_scope jsonb) returns jsonb language plpgsql volatile security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_monitor_scope_213();r jsonb;v public.pdc_supervised_rule_versions%rowtype;a uuid;e text;begin if not coalesce((s->>'ok')::boolean,false) then return public.navision_backend_response(false,'forbidden');end if;a=(s->'data'->>'actor_id')::uuid;e=s->'data'->>'actor_email';r:=public.review_pdc_supervised_email_line_213(null,nullif(p_scope->>'operation_code',''),p_scope->>'operation_description',p_scope->>'current_mapping');if not coalesce((r->>'ok')::boolean,false) or r->>'code'<>'deterministic_match' then if r->>'code'='inference_review_required' then insert into public.pdc_supervised_review_queue(operation_code,source_description,current_mapping,reason,scope,actor_id,actor_email) values(nullif(p_scope->>'operation_code',''),p_scope->>'operation_description',p_scope->>'current_mapping','No deterministic active rule and no existing mapping',p_scope,a,e);end if;return public.navision_backend_response(true,'active_lessons',jsonb_build_object('matched',false,'rule',null));end if;select * into v from public.pdc_supervised_rule_versions where version_id=(r->'data'->>'version_id')::uuid;return public.navision_backend_response(true,'active_lessons',jsonb_build_object('matched',true,'rule',jsonb_build_object('lesson_id',v.version_id,'version',v.version_no,'target_mapping',v.work_key,'estimated_hours',v.estimated_hours,'pricing',case when v.cost_ex_gst is null then null else jsonb_build_object('cost_ex_gst',to_char(v.cost_ex_gst,'FM999999990.00'),'sell_ex_gst',to_char(v.sell_ex_gst,'FM999999990.00'),'gst_percent',to_char(v.gst_percent,'FM990.00'),'currency',v.currency) end)));end$$;

create or replace function public.apply_pdc_supervised_correction_batch_213(p_batch_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_admin_scope_213();a uuid;e text;i record;l public.pdc_authenticated_email_operation_lines%rowtype;adj public.vehicle_workshop_line_adjustments%rowtype;o uuid;n int:=0;skip int:=0;last_outcome text;begin if not coalesce((s->>'ok')::boolean,false) then s:=public.pdc_supervised_monitor_scope_213();end if;if not coalesce((s->>'ok')::boolean,false) then return s;end if;a=(s->'data'->>'actor_id')::uuid;e=s->'data'->>'actor_email';for i in select * from public.pdc_supervised_correction_items where batch_id=p_batch_id order by operation_line_id loop begin select outcome into last_outcome from public.pdc_supervised_apply_receipts where batch_id=p_batch_id and operation_line_id=i.operation_line_id order by created_at desc,receipt_id desc limit 1;if last_outcome='applied' then skip:=skip+1;continue;end if;select * into l from public.pdc_authenticated_email_operation_lines where operation_line_id=i.operation_line_id for share;if not found then insert into public.pdc_supervised_apply_receipts(batch_id,operation_line_id,outcome,detail,actor_id,actor_email) values(p_batch_id,i.operation_line_id,'not_found','immutable source line absent',a,e);skip:=skip+1;continue;end if;if exists(select 1 from public.vehicles v where v.id=l.vehicle_id and (v.lifecycle_state<>'active' or v.deleted_at is not null or v.rft_collected_at is not null or upper(coalesce(v.current_location,''))='COMPLETED')) or exists(select 1 from public.vehicle_work_items w where w.vehicle_id=l.vehicle_id and w.completed) or exists(select 1 from public.pdc_auditor_finding_evidence ae where ae.entity_type='operation_line' and ae.entity_id=l.operation_line_id) or exists(select 1 from public.workshop_bookings b join public.workshop_stages st on st.id=b.stage_id where b.vehicle_id=l.vehicle_id and b.deleted_at is null and b.status::text not in('completed','cancelled') and st.code=coalesce(public.workshop_stage_code_for_work_key(l.work_key),upper(l.work_key))) then insert into public.pdc_supervised_apply_receipts(batch_id,operation_line_id,outcome,detail,actor_id,actor_email) values(p_batch_id,l.operation_line_id,'protected','completed/manual/Auditor/live-booking protected line',a,e);skip:=skip+1;continue;end if;select * into adj from public.vehicle_workshop_line_adjustments where vehicle_id=l.vehicle_id and line_key='source:'||l.operation_line_id::text for update;if found and last_outcome is null then insert into public.pdc_supervised_apply_receipts(batch_id,operation_line_id,outcome,detail,before_effective,actor_id,actor_email) values(p_batch_id,l.operation_line_id,'protected','pre-existing manual/authoritative overlay',to_jsonb(adj),a,e);skip:=skip+1;continue;end if;insert into public.pdc_supervised_correction_overlays(item_id,operation_line_id,overlay_kind,stage_code,actor_id,actor_email) values(i.item_id,l.operation_line_id,'apply',i.target_stage_code,a,e) returning overlay_id into o;if adj.adjustment_id is null then insert into public.vehicle_workshop_line_adjustments(vehicle_id,line_key,source_kind,stage_code,description,estimated_hours,active,version,created_by,updated_by) values(l.vehicle_id,'source:'||l.operation_line_id,'source',i.target_stage_code,l.description,l.estimated_hours,true,1,a,a) returning * into adj;else update public.vehicle_workshop_line_adjustments set stage_code=i.target_stage_code,version=version+1,updated_by=a,updated_at=clock_timestamp() where adjustment_id=adj.adjustment_id returning * into adj;end if;insert into public.pdc_supervised_apply_receipts(batch_id,operation_line_id,overlay_id,outcome,detail,after_effective,actor_id,actor_email) values(p_batch_id,l.operation_line_id,o,'applied','station-only correction overlay; no source/hour/booking/location/status mutation',to_jsonb(adj),a,e);n:=n+1;exception when others then insert into public.pdc_supervised_failures(rpc_name,error_code,error_detail,actor_id,actor_email,request_context) values('apply_pdc_supervised_correction_batch_213',sqlstate,sqlerrm,a,e,jsonb_build_object('batch_id',p_batch_id,'operation_line_id',i.operation_line_id));skip:=skip+1;end;end loop;return public.navision_backend_response(true,'correction_batch_applied',jsonb_build_object('batch_id',p_batch_id,'applied',n,'skipped',skip,'booking_changed',false,'location_changed',false,'status_changed',false));end$$;

create or replace function public.undo_pdc_supervised_rule_213(p_family_id uuid,p_reason text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_admin_scope_213();a uuid;e text;v uuid;prev uuid;begin if not coalesce((s->>'ok')::boolean,false) then return s;end if;a=(s->'data'->>'actor_id')::uuid;e=s->'data'->>'actor_email';select version_id into v from public.pdc_supervised_rule_versions where family_id=p_family_id order by version_no desc limit 1;if v is null then return public.navision_backend_response(false,'family_not_found');end if;insert into public.pdc_supervised_rule_events values(default,p_family_id,v,'undo',btrim(p_reason),a,e,default);select version_id into prev from public.pdc_supervised_rule_versions where family_id=p_family_id and version_id<>v order by version_no desc limit 1;if prev is not null then insert into public.pdc_supervised_rule_events values(default,p_family_id,prev,'activated','restored by undo',a,e,default);end if;return public.navision_backend_response(true,'rule_undone',jsonb_build_object('undone_version_id',v,'restored_version_id',prev));end$$;

revoke all on function public.read_pdc_supervised_learning_rule(jsonb) from public,anon,authenticated,service_role;
revoke all on function public.apply_pdc_supervised_correction_batch_213(uuid) from public,anon,authenticated,service_role;
revoke all on function public.undo_pdc_supervised_rule_213(uuid,text) from public,anon,authenticated,service_role;
grant execute on function public.read_pdc_supervised_learning_rule(jsonb) to authenticated;
grant execute on function public.apply_pdc_supervised_correction_batch_213(uuid) to authenticated;
grant execute on function public.undo_pdc_supervised_rule_213(uuid,text) to authenticated;
insert into supabase_migrations.schema_migrations(version,name,statements) values('214','supervised_learning_review_undo_hardening',array['append-only uncertain review queue','alias normalization and rule payload hours','reapply only after latest undo','undo restores previous version','preserve all role and staging guards']);
notify pgrst,'reload schema';
commit;
